<script>
$(function(){var t=$('#purchase-receipts-table'),x=$.fn.dataTable.render.text(),classes={DRAFT:'app-status-neutral',APPROVED:'app-status-success',VOID:'app-status-danger'};window.erpInitSelect2('#gr-filter-supplier',{placeholder:'ค้นหา Supplier',allowClear:true,ajax:{url:$('#gr-filter-supplier').data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(d){return d;}}});var table=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.business_date_from=$('#gr-filter-date-from').val();d.business_date_to=$('#gr-filter-date-to').val();d.supplier_id=$('#gr-filter-supplier').val();d.purchase_document_number=$('#gr-filter-purchase-document').val();d.status=$('#gr-filter-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[{data:'receipt_number',render:function(v,type,r){return type==='display'?'<a class="fw-semibold link-primary" href="'+x.display(r.show_url)+'">'+x.display(v)+'</a>':v;}},{data:'business_date',render:x.display},{data:'purchase_order_label',render:x.display},{data:'purchase_document_label',render:x.display},{data:'supplier_label',render:x.display},{data:'status_label',render:function(v,type,r){return type==='display'?'<span class="badge '+(classes[r.status]||'app-status-neutral')+'">'+x.display(v||'-')+'</span>':r.status;}},{data:'reason_label',render:function(v,type){return type==='display'&&v&&v!=='-'?'<span class="text-secondary" title="'+x.display(v)+'">'+x.display(v)+'</span>':(v||'-');}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(v,type,r){if(type!=='display')return '';var a=['<a class="btn btn-sm btn-app-soft" title="ดูรายละเอียด" aria-label="ดูรายละเอียด" href="'+x.display(r.show_url)+'"><i class="bx bx-file-find" aria-hidden="true"></i></a>'];if(r.edit_url)a.push('<a class="btn btn-sm btn-app-soft" title="แก้ไข" aria-label="แก้ไข" href="'+x.display(r.edit_url)+'"><i class="bx bx-edit" aria-hidden="true"></i></a>');if(r.print_url)a.push('<a class="btn btn-sm btn-app-soft" target="_blank" title="พิมพ์" aria-label="พิมพ์" href="'+x.display(r.print_url)+'"><i class="bx bx-printer" aria-hidden="true"></i></a>');if(r.delete_url)a.push('<button type="button" class="btn btn-sm btn-app-danger js-gr-delete" data-url="'+x.display(r.delete_url)+'" title="ลบร่าง" aria-label="ลบร่าง"><i class="bx bx-trash" aria-hidden="true"></i></button>');return a.join(' ');}}]}));$('#gr-filter-date-from,#gr-filter-date-to,#gr-filter-status').on('change',function(){table.ajax.reload();});$('#gr-filter-purchase-document').on('input',function(){clearTimeout(window.grDocFilterTimer);window.grDocFilterTimer=setTimeout(function(){table.ajax.reload();},300);});$('#gr-filter-supplier').on('change',function(){table.ajax.reload();});$('#gr-filter-reset').on('click',function(){$('#gr-filter-date-from,#gr-filter-date-to,#gr-filter-purchase-document,#gr-filter-status').val('');$('#gr-filter-supplier').val(null).trigger('change');table.ajax.reload();});window.erpAjaxDelete({button:'.js-gr-delete',reload:'#purchase-receipts-table',title:'ลบร่างใบรับสินค้า?',text:'เอกสารร่างจะถูกลบและไม่สามารถกู้คืนได้',confirmButtonText:'ลบร่าง',cancelButtonText:'กลับ'});});
</script>
